theorem poincare (rate : ℝ≥0) (hr : 0 < rate) {f : ScalarL2 rate} {g : FieldL2 rate}
    (hf : (f,g) ∈ (maximalDifference rate hr).graph) :
    ‖centered rate hr f‖ ≤ ‖g‖

theorem hasDerivAt_mehler_C1 (t : ℝ) {f : ℝ → ℝ}
    (hf_C1 : ContDiff ℝ 1 f) {M : ℝ}
    (hf_bd : ∀ x, ‖f x‖ ≤ M) (hf'_bd : ∀ x, ‖deriv f x‖ ≤ M)
    (x₀ : ℝ) :
    HasDerivAt (GaussianMehler.mehler t f)
      (Real.exp (-t) * GaussianMehler.mehler t (deriv f) x₀) x₀
